#!/usr/bin/env node/** * ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ *  BANF CRM UNIVERSE ENRICHMENT & REPORT GENERATOR * ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ * *  Pulls from ALL member data sources, builds unified universe, *  enriches CRM, and generates a comprehensive HTML report. * *  DATA SOURCES: *    1. Live CRM (Wix API)            ΓåÆ current CRMMembers *    2. Google Contacts JSON           ΓåÆ names, emails, phones *    3. Family Universe XLSX (v3)      ΓåÆ family groupings, yearly membership *    4. Membership 2025-26 XLSX        ΓåÆ payment/category data *    5. Family Fix Mapping JSON        ΓåÆ corrected family links *    6. Member Audit JSON              ΓåÆ full field dump from CRM *    7. CRM Comprehensive Data JSON    ΓåÆ issues, payments, comms *    8. Report 25-26 Admin JSON        ΓåÆ EC roles, org involvement *    9. Jagriti XLSX files             ΓåÆ magazine contributors *   10. GDrive search (via API)        ΓåÆ member files on Drive * *  USAGE: *    node banf-crm-universe-enrichment.js               # full run *    node banf-crm-universe-enrichment.js --dry-run      # preview only *    node banf-crm-universe-enrichment.js --report-only  # skip CRM updates *    node banf-crm-universe-enrichment.js --enrich       # also push updates to CRM * * ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ */const path = require('path');const fs   = require('fs');let XLSX;try { XLSX = require('xlsx'); } catch (_) {    console.error('Run: npm install xlsx'); process.exit(1);}const ARGS = process.argv.slice(2).reduce((a, x) => {    const [k,v] = x.replace(/^--/,'').split('='); a[k]=v||true; return a;}, {});const DRY_RUN = !!ARGS['dry-run'];const REPORT_ONLY = !!ARGS['report-only'];const ENRICH = !!ARGS['enrich'];const BASE_URL = 'https://banfwix.wixsite.com/banf1/_functions';const ADMIN_EMAIL = 'banfjax@gmail.com';const ROOT = 'c:\\projects\\banf';const DATA_ROOT = path.join(ROOT, 'banf1-wix', 'banf-data_ingest', 'data');const INGEST_ROOT = path.join(ROOT, 'banf1-wix', 'banf-data_ingest');// ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ// HELPERS// ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉasync function apiFetch(endpoint, method = 'GET', body = null) {    const { default: fetch } = await import('node-fetch');    const opts = {        method,        headers: { 'Content-Type': 'application/json', 'x-user-email': ADMIN_EMAIL }    };    if (body) opts.body = JSON.stringify(body);    const r = await fetch(`${BASE_URL}/${endpoint}`, opts);    return r.json();}function readJSON(filePath) {    try {        let raw = fs.readFileSync(filePath, 'utf8');        raw = raw.replace(/^\uFEFF/, ''); // strip BOM        return JSON.parse(raw);    } catch (e) { console.warn(`  [WARN] Cannot read ${filePath}: ${e.message}`); return null; }}function readXLSX(filePath, sheetIndex = 0) {    try {        const wb = XLSX.readFile(filePath);        const ws = wb.Sheets[wb.SheetNames[sheetIndex]];        return XLSX.utils.sheet_to_json(ws, { defval: '' });    } catch (e) { console.warn(`  [WARN] Cannot read ${filePath}: ${e.message}`); return []; }}function readAllXLSXSheets(filePath) {    try {        const wb = XLSX.readFile(filePath);        const result = {};        for (const sn of wb.SheetNames) {            result[sn] = XLSX.utils.sheet_to_json(wb.Sheets[sn], { defval: '' });        }        return result;    } catch (e) { console.warn(`  [WARN] Cannot read ${filePath}: ${e.message}`); return {}; }}function norm(s) { return (s || '').toLowerCase().trim(); }function titleCase(s) {    if (!s) return '';    return s.replace(/\b\w/g, c => c.toUpperCase()).replace(/\s+/g, ' ').trim();}// ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ// DATA LOADING// ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉasync function loadAllSources() {    const sources = {};    // 1. Live CRM members    console.log('  [1] Loading live CRM members...');    try {        const r = await apiFetch('crm_members?limit=500&skip=0');        sources.crmMembers = r.members || [];        console.log(`      ΓåÆ ${sources.crmMembers.length} CRM members`);    } catch (e) {        console.warn(`      ΓåÆ CRM API error: ${e.message}`);        sources.crmMembers = [];    }    // 2. Google Contacts    console.log('  [2] Loading Google Contacts...');    sources.googleContacts = readJSON(path.join(ROOT, 'google_contacts.json')) || [];    console.log(`      ΓåÆ ${sources.googleContacts.length} contacts`);    // 3. Family Universe v3 XLSX    console.log('  [3] Loading Family Universe v3...');    const fuSheets = readAllXLSXSheets(path.join(DATA_ROOT, 'BANF_Family_Universe_v3.xlsx'));    sources.familyUniverse = fuSheets['Family Universe'] || [];    sources.familyMembers = fuSheets['Family Members'] || [];    sources.yearlyMembership = fuSheets['Yearly Membership'] || [];    sources.rawEntries = fuSheets['Raw Entries'] || [];    console.log(`      ΓåÆ ${sources.familyUniverse.length} families, ${sources.familyMembers.length} individuals, ${sources.yearlyMembership.length} yearly records`);    // 4. Membership 2025-26 XLSX    console.log('  [4] Loading Membership 2025-26...');    sources.membership2526 = readXLSX(path.join(DATA_ROOT, 'BANF Membership 2025 - 26.xlsx'));    console.log(`      ΓåÆ ${sources.membership2526.length} membership records`);    // 5. Family Fix Mapping    console.log('  [5] Loading Family Fix Mapping...');    const ffm = readJSON(path.join(ROOT, 'family-fix-mapping.json'));    sources.familyFixMapping = ffm ? ffm.families : [];    console.log(`      ΓåÆ ${sources.familyFixMapping.length} families`);    // 6. Member Audit    console.log('  [6] Loading Member Audit...');    const ma = readJSON(path.join(ROOT, 'member-audit-all.json'));    sources.memberAudit = ma ? ma.members : [];    console.log(`      ΓåÆ ${sources.memberAudit.length} members`);    // 7. CRM Comprehensive Data    console.log('  [7] Loading CRM Comprehensive Data...');    const cd = readJSON(path.join(ROOT, 'crm-comprehensive-data.json'));    sources.crmComprehensive = cd ? (cd.members || []) : [];    console.log(`      ΓåÆ ${sources.crmComprehensive.length} members`);    // 8. Report 25-26 Admin (EC roles)    console.log('  [8] Loading Report 25-26 Admin...');    const ra = readJSON(path.join(ROOT, 'report_25-26_admin.json'));    sources.adminReport = ra;    console.log(`      ΓåÆ ${ra ? 'loaded' : 'not found'}`);    // 9. Jagriti files    console.log('  [9] Loading Jagriti contributor data...');    sources.jagriti2022 = readXLSX(path.join(DATA_ROOT, '24-26EC', 'Jagriti 2022.xlsx'));    sources.jagriti2023 = readXLSX(path.join(DATA_ROOT, '24-26EC', 'Jagriti 2023.xlsx'));    console.log(`      ΓåÆ Jagriti 2022: ${sources.jagriti2022.length}, 2023: ${sources.jagriti2023.length}`);    // 10. Report 25-26 family mapping    console.log(' [10] Loading Report family mapping...');    const rfm = readJSON(path.join(ROOT, 'report_25-26_family_mapping.json'));    sources.reportFamilyMapping = rfm && rfm.mapping && rfm.mapping.families ? rfm.mapping.families : [];    sources.reportUnmapped = rfm && rfm.mapping && rfm.mapping.unmapped ? rfm.mapping.unmapped : [];    console.log(`      ΓåÆ ${sources.reportFamilyMapping.length} families`);    return sources;}// ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ// UNIVERSE BUILDER// ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉfunction buildUniverse(sources) {    const universe = new Map(); // email ΓåÆ unified record    function getOrCreate(email) {        const key = norm(email);        if (!key || !key.includes('@')) return null;        if (!universe.has(key)) {            universe.set(key, {                email: key,                firstName: '', lastName: '', displayName: '',                phone: '', phone2: '', address: '', city: '', state: '', zip: '',                familyId: '', familyType: '', familyDisplayName: '',                memberId: '',                membershipYears: new Set(),                membershipTypes: new Set(),                paymentRecords: [],                orgRoles: [],                awards: [],                volunteer: [],                communications: 0,                jagritiContributions: [],                importSources: new Set(),                isECMember: false,                isBOTMember: false,                isActive: true,                memberSince: '',                memberType: 'adult',                profession: '', employer: '',                gender: '',                issues: [],                raw: {}            });        }        return universe.get(key);    }    function mergeField(rec, field, value) {        if (!value || value === '' || value === 'N/A') return;        const v = String(value).trim();        if (!rec[field] || rec[field] === '' || rec[field] === rec.email) {            rec[field] = v;        }    }    // ΓöÇΓöÇ Source 1: Live CRM ΓöÇΓöÇ    console.log('  Merging CRM members...');    for (const m of sources.crmMembers) {        if (!m.email) continue;        const rec = getOrCreate(m.email);        if (!rec) continue;        mergeField(rec, 'firstName', m.firstName);        mergeField(rec, 'lastName', m.lastName);        mergeField(rec, 'displayName', m.displayName);        mergeField(rec, 'phone', m.phone);        mergeField(rec, 'phone2', m.phone2);        mergeField(rec, 'address', m.address);        mergeField(rec, 'city', m.city);        mergeField(rec, 'state', m.state);        mergeField(rec, 'zip', m.zip);        mergeField(rec, 'familyId', m.familyId);        mergeField(rec, 'familyType', m.familyType);        mergeField(rec, 'memberId', m.memberId);        mergeField(rec, 'memberSince', m.memberSince);        mergeField(rec, 'memberType', m.memberType);        mergeField(rec, 'profession', m.profession);        mergeField(rec, 'employer', m.employer);        mergeField(rec, 'gender', m.gender);        rec.isECMember = rec.isECMember || m.isECMember;        rec.isBOTMember = rec.isBOTMember || m.isBOTMember;        rec.isActive = m.isActive !== false;        if (m.membershipType) rec.membershipTypes.add(m.membershipType);        rec.importSources.add('crm');        rec.raw.crm = m;    }    // ΓöÇΓöÇ Source 2: Google Contacts ΓöÇΓöÇ    console.log('  Merging Google Contacts...');    for (const c of sources.googleContacts) {        if (!c.email) continue;        const rec = getOrCreate(c.email);        if (!rec) continue;        mergeField(rec, 'firstName', c.firstName);        mergeField(rec, 'lastName', c.lastName);        mergeField(rec, 'displayName', c.displayName);        mergeField(rec, 'phone', c.phone);        rec.importSources.add('google_contacts');    }    // ΓöÇΓöÇ Source 3: Family Universe XLSX ΓöÇΓöÇ    console.log('  Merging Family Universe...');    // Build a family ID ΓåÆ yearly data map    const fuYearlyMap = {};    for (const ym of sources.yearlyMembership) {        const fid = ym['Family ID'];        fuYearlyMap[fid] = ym;    }    // Build family member map: famID ΓåÆ members    const fuFamilyMap = {};    for (const fm of sources.familyMembers) {        const fid = fm['Family ID'];        if (!fuFamilyMap[fid]) fuFamilyMap[fid] = [];        fuFamilyMap[fid].push(fm);    }    // ΓöÇΓöÇ Source 4: Membership 2025-26 ΓöÇΓöÇ    console.log('  Merging Membership 2025-26...');    sources._unmatchedMembership = [];        // Build lookup indices for faster matching    const emailByFirst = {};   // firstName ΓåÆ [email]    const emailByLast = {};    // lastName  ΓåÆ [email]    const emailByFull = {};    // "first last" ΓåÆ email    const emailByDisplay = {}; // displayName ΓåÆ email    for (const [email, rec] of universe) {        const f = norm(rec.firstName), l = norm(rec.lastName);        const full = `${f} ${l}`.trim();        const disp = norm(rec.displayName);        if (f) { (emailByFirst[f] = emailByFirst[f] || []).push(email); }        if (l) { (emailByLast[l] = emailByLast[l] || []).push(email); }        if (full && full !== ' ') emailByFull[full] = email;        if (disp) emailByDisplay[disp] = email;    }    function stripHonorifics(s) {        return s.replace(/\b(da|di|dada|didi|uncle|aunty|auntie|sis|bro)\b/gi, '').trim();    }    function stripParens(s) {        return s.replace(/\(.*?\)/g, '').trim();    }    function findBestMatch(rawName) {        const cleaned = stripParens(stripHonorifics(rawName.trim())).toLowerCase().replace(/\s+/g, ' ').trim();        if (!cleaned) return null;        // Exact full or display match        if (emailByFull[cleaned]) return emailByFull[cleaned];        if (emailByDisplay[cleaned]) return emailByDisplay[cleaned];        const parts = cleaned.split(/\s+/);        const first = parts[0], last = parts.slice(1).join(' ');        // First + Last exact        if (first && last && emailByFull[`${first} ${last}`]) return emailByFull[`${first} ${last}`];        // First + Last prefix (4 chars)        if (first && last && last.length >= 3) {            for (const [full, em] of Object.entries(emailByFull)) {                const fp = full.split(' ');                if (fp[0] === first && fp.slice(1).join(' ').startsWith(last.substring(0,4))) return em;                if (fp[0] === first && last.startsWith(fp.slice(1).join(' ').substring(0,4))) return em;            }        }        // First name only match (if unique)        if (first && emailByFirst[first] && emailByFirst[first].length === 1) return emailByFirst[first][0];        // Last name only match (if unique and last is substantial)        if (last && last.length >= 4 && emailByLast[last] && emailByLast[last].length === 1) return emailByLast[last][0];        // Last name match where first name starts the same (2+ chars)        if (first && last) {            const candidates = emailByLast[last] || [];            for (const em of candidates) {                const rec = universe.get(em);                if (rec && norm(rec.firstName).startsWith(first.substring(0,2))) return em;            }        }        return null;    }    for (const m of sources.membership2526) {        const rawName = (m.Name || '').trim();        const category = m.Category || '';        const amount = m.Amount || 0;        if (!rawName) continue;        // Split on / or & for couple entries        const nameParts = rawName.split(/[\/&]/).map(n => n.trim()).filter(Boolean);                // If a surname appears at end, apply it to parts missing a surname        const lastPart = nameParts[nameParts.length - 1];        const lastPartWords = lastPart.split(/\s+/);        const sharedSurname = lastPartWords.length >= 2 ? lastPartWords[lastPartWords.length - 1] : '';        let anyMatched = false;        for (let np of nameParts) {            // If this part is a single name with no surname, try appending shared surname            const words = stripParens(stripHonorifics(np)).trim().split(/\s+/).filter(Boolean);            if (words.length === 1 && sharedSurname && words[0].toLowerCase() !== sharedSurname.toLowerCase()) {                np = `${words[0]} ${sharedSurname}`;            }                        const matchEmail = findBestMatch(np);            if (matchEmail) {                const rec = universe.get(matchEmail);                if (rec) {                    rec.membershipTypes.add(category);                    rec.membershipYears.add('2025-26');                    rec.paymentRecords.push({ year: '2025-26', category, amount: amount / nameParts.length, source: 'membership_xlsx' });                    rec.importSources.add('membership_2526');                    anyMatched = true;                }            }        }                if (!anyMatched) {            sources._unmatchedMembership.push({ name: rawName, category, amount });        }    }    console.log(`      ΓåÆ Matched: ${sources.membership2526.filter(r=>r.Name&&r.Name.trim()).length - sources._unmatchedMembership.length}/${sources.membership2526.filter(r=>r.Name&&r.Name.trim()).length}, Unmatched: ${sources._unmatchedMembership.length}`);    // ΓöÇΓöÇ Source 5: Family Fix Mapping ΓöÇΓöÇ    console.log('  Merging Family Fix Mapping...');    for (const fam of sources.familyFixMapping) {        for (const m of fam.members || []) {            if (!m.email) continue;            const rec = getOrCreate(m.email);            if (!rec) continue;            mergeField(rec, 'firstName', m.firstName);            mergeField(rec, 'lastName', m.lastName);            mergeField(rec, 'memberId', m.memberId);            mergeField(rec, 'familyId', fam.familyId);            mergeField(rec, 'familyType', fam.familyType);            mergeField(rec, 'familyDisplayName', fam.displayName);            rec.importSources.add('family_fix');        }    }    // ΓöÇΓöÇ Source 6: Member Audit ΓöÇΓöÇ    console.log('  Merging Member Audit...');    for (const m of sources.memberAudit) {        if (!m.email) continue;        const rec = getOrCreate(m.email);        if (!rec) continue;        mergeField(rec, 'firstName', m.firstName === m.email ? '' : m.firstName);        mergeField(rec, 'lastName', m.lastName);        mergeField(rec, 'phone', m.phone);        mergeField(rec, 'address', m.address);        mergeField(rec, 'city', m.city);        mergeField(rec, 'state', m.state);        mergeField(rec, 'zip', m.zip);        mergeField(rec, 'familyId', m.familyId);        mergeField(rec, 'memberId', m.memberId);        mergeField(rec, 'memberSince', m.memberSince);        mergeField(rec, 'gender', m.gender);        mergeField(rec, 'profession', m.profession);        mergeField(rec, 'employer', m.employer);        rec.importSources.add('member_audit');    }    // ΓöÇΓöÇ Source 7: CRM Comprehensive ΓöÇΓöÇ    console.log('  Merging CRM Comprehensive...');    for (const m of sources.crmComprehensive) {        if (!m.email) continue;        const rec = getOrCreate(m.email);        if (!rec) continue;        rec.communications = Math.max(rec.communications, m.communications || 0);        if (m.payments) rec.paymentRecords.push(...(m.paymentRecords || []));        if (m.issues) rec.issues = m.issues;        rec.importSources.add('crm_comprehensive');    }    // ΓöÇΓöÇ Source 8: Admin Report (EC roles) ΓöÇΓöÇ    console.log('  Merging Admin Report EC roles...');    if (sources.adminReport && sources.adminReport.report) {        const rpt = sources.adminReport.report;        for (const term of (rpt.ecTerms || [])) {            for (const c of (term.contacts || [])) {                if (!c.email) continue;                const rec = getOrCreate(c.email);                if (!rec) continue;                const cName = c.name || c.firstName || '';                mergeField(rec, 'firstName', cName.split(' ')[0]);                mergeField(rec, 'lastName', cName.split(' ').slice(1).join(' '));                if (c.phone) mergeField(rec, 'phone', c.phone);                if (c.categories && c.categories.includes('EC')) rec.isECMember = true;                if (c.categories && c.categories.includes('BOT')) rec.isBOTMember = true;                for (const role of (c.roles || [])) {                    const roleName = typeof role === 'string' ? role : role.role || role.label || JSON.stringify(role);                    rec.orgRoles.push({ term: term.term, role: roleName, source: 'admin_report' });                }                rec.importSources.add('admin_report');            }        }    }    // ΓöÇΓöÇ Source 9: Jagriti contributors ΓöÇΓöÇ    console.log('  Merging Jagriti contributors...');    for (const j of sources.jagriti2022) {        if (j.Contributor) {            // Match by name            for (const [email, rec] of universe) {                const full = `${rec.firstName} ${rec.lastName}`.toLowerCase();                if (full.includes(j.Contributor.toLowerCase()) || j.Contributor.toLowerCase().includes(full)) {                    rec.jagritiContributions.push({ year: '2022', type: j.Type || 'contributor', source: 'jagriti_2022' });                    rec.importSources.add('jagriti');                    break;                }            }        }    }    for (const j of sources.jagriti2023) {        if (j.Contributor) {            for (const [email, rec] of universe) {                const full = `${rec.firstName} ${rec.lastName}`.toLowerCase();                if (full.includes(j.Contributor.toLowerCase()) || j.Contributor.toLowerCase().includes(full)) {                    rec.jagritiContributions.push({ year: '2023', type: j.Type || 'contributor', source: 'jagriti_2023' });                    rec.importSources.add('jagriti');                    break;                }            }        }    }    // ΓöÇΓöÇ Source 10: Report Family Mapping ΓöÇΓöÇ    console.log('  Merging Report Family Mapping...');    for (const fam of sources.reportFamilyMapping) {        for (const m of (fam.members || [])) {            if (!m.email) continue;            const rec = getOrCreate(m.email);            if (!rec) continue;            mergeField(rec, 'displayName', m.name);            if (!rec.firstName && m.name) {                mergeField(rec, 'firstName', m.name.split(' ')[0]);                mergeField(rec, 'lastName', m.name.split(' ').slice(1).join(' '));            }            rec.importSources.add('report_family_mapping');        }    }    // ΓöÇΓöÇ Cross-reference Family Universe yearly data ΓöÇΓöÇ    console.log('  Cross-referencing yearly membership...');    for (const [fid, ym] of Object.entries(fuYearlyMap)) {        const years = ['2022-23', '2023-24', '2024-25', '2025-26'];        const memberNames = (ym.Members || '').split(',').map(n => n.trim().toLowerCase());        for (const [email, rec] of universe) {            const fn = rec.firstName.toLowerCase();            if (memberNames.some(n => n === fn || n.includes(fn))) {                for (const yr of years) {                    if (ym[yr] === 'Γ£ô' || ym[yr] === true) {                        rec.membershipYears.add(yr);                    }                }            }        }    }    // ΓöÇΓöÇ Fix names that are just email addresses ΓöÇΓöÇ    console.log('  Fixing name-is-email records...');    for (const [email, rec] of universe) {        if (rec.firstName === email || rec.firstName === '') {            // Try to get from displayName            if (rec.displayName && rec.displayName !== email) {                const parts = rec.displayName.split(' ');                rec.firstName = parts[0] || '';                rec.lastName = parts.slice(1).join(' ') || '';            }        }        // Title case names        rec.firstName = titleCase(rec.firstName);        rec.lastName = titleCase(rec.lastName);        if (!rec.displayName || rec.displayName === email) {            rec.displayName = [rec.firstName, rec.lastName].filter(Boolean).join(' ') || email;        }        // Convert Sets to Arrays for JSON serialization        rec.membershipYears = [...rec.membershipYears].sort();        rec.membershipTypes = [...rec.membershipTypes];        rec.importSources = [...rec.importSources];    }    return universe;}// ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ// CRM ENRICHMENT// ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉasync function enrichCRM(universe) {    if (REPORT_ONLY || DRY_RUN) {        console.log('  [SKIP] CRM enrichment (report-only or dry-run mode)');        return { updated: 0, errors: [] };    }    let updated = 0, errors = [];    const entries = [...universe.entries()];    for (let i = 0; i < entries.length; i++) {        const [email, rec] = entries[i];        if (!rec.raw.crm) continue; // Only update existing CRM records        const crm = rec.raw.crm;        const updates = {};        let needsUpdate = false;        // Enrich missing fields        if ((!crm.firstName || crm.firstName === crm.email) && rec.firstName && rec.firstName !== email) {            updates.firstName = rec.firstName; needsUpdate = true;        }        if (!crm.lastName && rec.lastName) {            updates.lastName = rec.lastName; needsUpdate = true;        }        if (!crm.phone && rec.phone) {            updates.phone = rec.phone; needsUpdate = true;        }        if (!crm.phone2 && rec.phone2) {            updates.phone2 = rec.phone2; needsUpdate = true;        }        if (!crm.displayName && rec.displayName && rec.displayName !== email) {            updates.displayName = rec.displayName; needsUpdate = true;        }        if (needsUpdate && ENRICH) {            try {                const result = await apiFetch('crm_member_update', 'POST', {                    memberId: crm.memberId,                    ...updates                });                if (result.success) {                    updated++;                    process.stdout.write(`  Updated ${crm.memberId} (${email}) [${i+1}/${entries.length}]\r`);                } else {                    errors.push({ email, error: result.error });                }                await new Promise(r => setTimeout(r, 200)); // rate limit            } catch (e) {                errors.push({ email, error: e.message });            }        } else if (needsUpdate) {            updated++; // Count what would be updated        }    }    console.log(`\n  CRM enrichment: ${updated} updated, ${errors.length} errors`);    return { updated, errors };}// ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ// HTML REPORT GENERATOR// ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉfunction generateReport(universe, sources, enrichResult) {    const members = [...universe.values()].sort((a,b) => a.displayName.localeCompare(b.displayName));    // Stats    const totalMembers = members.length;    const withEmail = members.filter(m => m.email).length;    const withPhone = members.filter(m => m.phone).length;    const withFamily = members.filter(m => m.familyId).length;    const ecMembers = members.filter(m => m.isECMember).length;    const multiYear = members.filter(m => m.membershipYears.length > 1).length;    const noName = members.filter(m => !m.firstName || m.firstName === m.email).length;    const sourceCount = {};    for (const m of members) {        for (const s of m.importSources) {            sourceCount[s] = (sourceCount[s] || 0) + 1;        }    }    // Family stats    const familyMap = {};    for (const m of members) {        if (m.familyId) {            if (!familyMap[m.familyId]) familyMap[m.familyId] = [];            familyMap[m.familyId].push(m);        }    }    const totalFamilies = Object.keys(familyMap).length;    // Unmatched membership names (from XLSX, no email match)    const unmatchedNames = sources._unmatchedMembership || [];    const html = `<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"/><meta name="viewport" content="width=device-width,initial-scale=1"/><title>BANF CRM Universe Report</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.2/dist/css/bootstrap.min.css" rel="stylesheet"><link href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.1/css/all.min.css" rel="stylesheet"><style>:root{--bg:#060a10;--bg2:#0b1120;--card:#0f172a;--panel:#111827;--line:#1e293b;--text:#e2e8f0;--muted:#94a3b8;--dim:#475569;--accent:#f97316;--green:#22c55e;--red:#ef4444;--blue:#3b82f6;--purple:#a855f7;--cyan:#06b6d4;--yellow:#eab308}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font-family:'Segoe UI',system-ui,-apple-system,sans-serif}.header{background:linear-gradient(135deg,var(--card),var(--bg2));border-bottom:1px solid var(--line);padding:24px 32px}.header h1{font-size:1.4rem;color:var(--accent);margin:0}.header small{color:var(--muted);font-size:.78rem}.container-fluid{padding:20px 32px}.stat-card{background:var(--card);border:1px solid var(--line);border-radius:12px;padding:20px;text-align:center}.stat-card .num{font-size:2rem;font-weight:800;color:var(--accent)}.stat-card .lbl{font-size:.78rem;color:var(--muted);margin-top:4px}.source-badge{display:inline-block;padding:2px 8px;border-radius:4px;font-size:.65rem;font-weight:700;margin:1px}.source-badge.crm{background:rgba(59,130,246,.2);color:#60a5fa}.source-badge.google{background:rgba(34,197,94,.2);color:#4ade80}.source-badge.family{background:rgba(168,85,247,.2);color:#c084fc}.source-badge.membership{background:rgba(249,115,22,.2);color:#fb923c}.source-badge.audit{background:rgba(6,182,212,.2);color:#22d3ee}.source-badge.jagriti{background:rgba(236,72,153,.2);color:#f472b6}.source-badge.admin{background:rgba(234,179,8,.2);color:#facc15}.source-badge.other{background:rgba(148,163,184,.2);color:#94a3b8}table{width:100%;border-collapse:collapse;font-size:.82rem}th{background:var(--bg2);color:var(--muted);padding:10px 12px;text-align:left;border-bottom:2px solid var(--line);position:sticky;top:0;z-index:1}td{padding:8px 12px;border-bottom:1px solid var(--line)}tr:hover td{background:rgba(249,115,22,.04)}.search-box{background:var(--bg2);border:1px solid var(--line);color:var(--text);padding:10px 16px;border-radius:8px;width:100%;font-size:.88rem;margin-bottom:16px}.search-box:focus{outline:none;border-color:var(--accent)}.badge-pill{display:inline-block;padding:2px 8px;border-radius:12px;font-size:.65rem;font-weight:700}.badge-active{background:rgba(34,197,94,.15);color:var(--green)}.badge-ec{background:rgba(249,115,22,.15);color:var(--accent)}.badge-year{background:rgba(59,130,246,.1);color:var(--blue);margin:1px;font-size:.6rem;padding:1px 6px;border-radius:4px}.detail-panel{display:none;background:var(--bg2);border:1px solid var(--line);border-radius:10px;padding:20px;margin:8px 0}.detail-panel.active{display:block}.detail-section{margin-bottom:14px}.detail-section h6{color:var(--accent);font-size:.78rem;margin-bottom:6px;text-transform:uppercase;letter-spacing:.5px}.detail-grid{display:grid;grid-template-columns:140px 1fr;gap:4px 12px;font-size:.8rem}.detail-grid .lbl{color:var(--dim);font-weight:600}.detail-grid .val{color:var(--text)}.tab-btn{background:var(--bg2);border:1px solid var(--line);color:var(--muted);padding:8px 18px;border-radius:8px 8px 0 0;cursor:pointer;font-size:.82rem;font-weight:600}.tab-btn.active{background:var(--card);color:var(--accent);border-bottom-color:var(--card)}.tab-content{display:none;background:var(--card);border:1px solid var(--line);border-top:none;border-radius:0 0 12px 12px;padding:20px}.tab-content.active{display:block}.issue-warning{color:var(--yellow);font-size:.72rem}.issue-error{color:var(--red);font-size:.72rem}.issue-info{color:var(--blue);font-size:.72rem}.plan-step{background:var(--card);border:1px solid var(--line);border-radius:8px;padding:14px;margin-bottom:10px}.plan-step h6{color:var(--accent);margin:0 0 4px}.plan-step p{color:var(--muted);font-size:.78rem;margin:0}.plan-step .status{float:right;font-size:.7rem;padding:2px 8px;border-radius:4px}.plan-step .status.done{background:rgba(34,197,94,.15);color:var(--green)}.plan-step .status.pending{background:rgba(234,179,8,.15);color:var(--yellow)}.plan-step .status.todo{background:rgba(148,163,184,.15);color:var(--muted)}#memberCount{color:var(--accent);font-weight:700}.family-tag{background:rgba(168,85,247,.1);color:var(--purple);padding:1px 6px;border-radius:4px;font-size:.65rem}</style></head><body><div class="header">  <h1><i class="fas fa-database me-2"></i>BANF CRM Universe Report</h1>  <small>Generated: ${new Date().toLocaleString()} | Total Universe: ${totalMembers} members | ${totalFamilies} families</small></div><div class="container-fluid"><!-- TABS --><div style="display:flex;gap:4px;margin-bottom:0">  <div class="tab-btn active" onclick="showTab('overview')"><i class="fas fa-chart-pie me-1"></i>Overview</div>  <div class="tab-btn" onclick="showTab('members')"><i class="fas fa-users me-1"></i>Members</div>  <div class="tab-btn" onclick="showTab('families')"><i class="fas fa-people-roof me-1"></i>Families</div>  <div class="tab-btn" onclick="showTab('gaps')"><i class="fas fa-exclamation-triangle me-1"></i>Data Gaps</div>  <div class="tab-btn" onclick="showTab('plan')"><i class="fas fa-clipboard-list me-1"></i>Enrichment Plan</div>  <div class="tab-btn" onclick="showTab('sources')"><i class="fas fa-layer-group me-1"></i>Sources</div></div><!-- ΓòÉΓòÉΓòÉ TAB: OVERVIEW ΓòÉΓòÉΓòÉ --><div class="tab-content active" id="tab-overview">  <div class="row g-3 mb-4">    <div class="col-md-2"><div class="stat-card"><div class="num">${totalMembers}</div><div class="lbl">Total Universe</div></div></div>    <div class="col-md-2"><div class="stat-card"><div class="num">${withEmail}</div><div class="lbl">With Email</div></div></div>    <div class="col-md-2"><div class="stat-card"><div class="num">${withPhone}</div><div class="lbl">With Phone</div></div></div>    <div class="col-md-2"><div class="stat-card"><div class="num">${totalFamilies}</div><div class="lbl">Families</div></div></div>    <div class="col-md-2"><div class="stat-card"><div class="num">${ecMembers}</div><div class="lbl">EC Members</div></div></div>    <div class="col-md-2"><div class="stat-card"><div class="num">${multiYear}</div><div class="lbl">Multi-Year</div></div></div>  </div>  <div class="row g-3">    <div class="col-md-6">      <div style="background:var(--card);border:1px solid var(--line);border-radius:12px;padding:20px">        <h6 style="color:var(--accent)"><i class="fas fa-layer-group me-1"></i>Data Sources Coverage</h6>        <table>          <tr><th>Source</th><th>Members</th><th>Coverage</th></tr>          ${Object.entries(sourceCount).sort((a,b) => b[1]-a[1]).map(([s,c]) =>            `<tr><td><span class="source-badge ${s.includes('crm') ? 'crm' : s.includes('google') ? 'google' : s.includes('family') ? 'family' : s.includes('membership') ? 'membership' : s.includes('audit') ? 'audit' : s.includes('jagriti') ? 'jagriti' : s.includes('admin') ? 'admin' : 'other'}">${s}</span></td><td>${c}</td><td>${(c/totalMembers*100).toFixed(1)}%</td></tr>`          ).join('\n          ')}        </table>      </div>    </div>    <div class="col-md-6">      <div style="background:var(--card);border:1px solid var(--line);border-radius:12px;padding:20px">        <h6 style="color:var(--accent)"><i class="fas fa-exclamation-triangle me-1"></i>Data Quality Summary</h6>        <table>          <tr><th>Metric</th><th>Count</th><th>%</th></tr>          <tr><td>Missing phone</td><td>${totalMembers - withPhone}</td><td style="color:var(--yellow)">${((totalMembers-withPhone)/totalMembers*100).toFixed(1)}%</td></tr>          <tr><td>Missing family link</td><td>${totalMembers - withFamily}</td><td style="color:var(--yellow)">${((totalMembers-withFamily)/totalMembers*100).toFixed(1)}%</td></tr>          <tr><td>Name = email (bad)</td><td>${noName}</td><td style="color:${noName > 0 ? 'var(--red)' : 'var(--green)'}">${(noName/totalMembers*100).toFixed(1)}%</td></tr>          <tr><td>No membership year</td><td>${members.filter(m => m.membershipYears.length === 0).length}</td><td style="color:var(--yellow)">${(members.filter(m => m.membershipYears.length === 0).length/totalMembers*100).toFixed(1)}%</td></tr>          <tr><td>Unmatched XLSX names</td><td>${unmatchedNames.length}</td><td style="color:var(--yellow)">ΓÇö</td></tr>        </table>      </div>    </div>  </div>  ${enrichResult && enrichResult.updated > 0 ? `  <div style="background:rgba(34,197,94,.08);border:1px solid rgba(34,197,94,.3);border-radius:8px;padding:14px;margin-top:16px">    <i class="fas fa-check-circle me-1" style="color:var(--green)"></i>    <strong style="color:var(--green)">CRM Enrichment:</strong>    <span style="color:var(--muted)">${enrichResult.updated} records updated, ${enrichResult.errors.length} errors</span>  </div>` : ''}</div><!-- ΓòÉΓòÉΓòÉ TAB: MEMBERS ΓòÉΓòÉΓòÉ --><div class="tab-content" id="tab-members">  <input class="search-box" id="memberSearch" placeholder="Search by name, email, phone, family..." oninput="filterMembers()">  <div style="font-size:.78rem;color:var(--muted);margin-bottom:12px">Showing <span id="memberCount">${totalMembers}</span> of ${totalMembers} members</div>  <div style="max-height:70vh;overflow-y:auto">    <table id="memberTable">      <thead>        <tr>          <th style="width:30px">#</th>          <th>Name</th>          <th>Email</th>          <th>Phone</th>          <th>Family</th>          <th>Years</th>          <th>Sources</th>          <th style="width:50px"></th>        </tr>      </thead>      <tbody>        ${members.map((m, i) => `        <tr class="member-row" data-idx="${i}" data-search="${norm(m.displayName + ' ' + m.email + ' ' + m.phone + ' ' + m.familyDisplayName + ' ' + m.firstName + ' ' + m.lastName)}">          <td style="color:var(--dim)">${i+1}</td>          <td><strong>${m.displayName || m.email}</strong>${m.isECMember ? ' <span class="badge-pill badge-ec">EC</span>' : ''}${m.isActive ? '' : ' <span class="badge-pill" style="background:rgba(239,68,68,.15);color:var(--red)">Inactive</span>'}</td>          <td style="font-size:.75rem;color:var(--muted)">${m.email}</td>          <td style="font-size:.78rem">${m.phone || '<span style="color:var(--dim)">ΓÇö</span>'}</td>          <td>${m.familyDisplayName ? `<span class="family-tag">${m.familyDisplayName}</span>` : m.familyId ? `<span class="family-tag">${m.familyId.substring(0,12)}</span>` : '<span style="color:var(--dim)">ΓÇö</span>'}</td>          <td>${m.membershipYears.map(y => `<span class="badge-year">${y}</span>`).join('') || '<span style="color:var(--dim)">ΓÇö</span>'}</td>          <td>${m.importSources.map(s => `<span class="source-badge ${s.includes('crm') ? 'crm' : s.includes('google') ? 'google' : s.includes('family') ? 'family' : s.includes('membership') ? 'membership' : s.includes('audit') ? 'audit' : s.includes('jagriti') ? 'jagriti' : s.includes('admin') ? 'admin' : 'other'}">${s.replace(/_/g,' ')}</span>`).join('')}</td>          <td><i class="fas fa-chevron-down" style="color:var(--dim);cursor:pointer" onclick="toggleDetail(${i})"></i></td>        </tr>        <tr class="detail-row" id="detail-${i}" style="display:none">          <td colspan="8">            <div class="detail-panel active">              <div class="row">                <div class="col-md-4">                  <div class="detail-section">                    <h6><i class="fas fa-user me-1"></i>Personal Info</h6>                    <div class="detail-grid">                      <div class="lbl">First Name</div><div class="val">${m.firstName || 'ΓÇö'}</div>                      <div class="lbl">Last Name</div><div class="val">${m.lastName || 'ΓÇö'}</div>                      <div class="lbl">Email</div><div class="val">${m.email}</div>                      <div class="lbl">Phone</div><div class="val">${m.phone || 'ΓÇö'}</div>                      <div class="lbl">Phone 2</div><div class="val">${m.phone2 || 'ΓÇö'}</div>                      <div class="lbl">Gender</div><div class="val">${m.gender || 'ΓÇö'}</div>                      <div class="lbl">Member Since</div><div class="val">${m.memberSince || 'ΓÇö'}</div>                      <div class="lbl">Member ID</div><div class="val" style="font-size:.7rem">${m.memberId || 'ΓÇö'}</div>                    </div>                  </div>                </div>                <div class="col-md-4">                  <div class="detail-section">                    <h6><i class="fas fa-map-marker-alt me-1"></i>Address & Professional</h6>                    <div class="detail-grid">                      <div class="lbl">Address</div><div class="val">${m.address || 'ΓÇö'}</div>                      <div class="lbl">City</div><div class="val">${m.city || 'ΓÇö'}</div>                      <div class="lbl">State</div><div class="val">${m.state || 'ΓÇö'}</div>                      <div class="lbl">ZIP</div><div class="val">${m.zip || 'ΓÇö'}</div>                      <div class="lbl">Profession</div><div class="val">${m.profession || 'ΓÇö'}</div>                      <div class="lbl">Employer</div><div class="val">${m.employer || 'ΓÇö'}</div>                    </div>                  </div>                </div>                <div class="col-md-4">                  <div class="detail-section">                    <h6><i class="fas fa-people-roof me-1"></i>Family & Membership</h6>                    <div class="detail-grid">                      <div class="lbl">Family ID</div><div class="val" style="font-size:.7rem">${m.familyId || 'ΓÇö'}</div>                      <div class="lbl">Family Type</div><div class="val">${m.familyType || 'ΓÇö'}</div>                      <div class="lbl">Family Name</div><div class="val">${m.familyDisplayName || 'ΓÇö'}</div>                      <div class="lbl">Member Type</div><div class="val">${m.memberType || 'ΓÇö'}</div>                      <div class="lbl">Years Active</div><div class="val">${m.membershipYears.join(', ') || 'ΓÇö'}</div>                      <div class="lbl">Types</div><div class="val">${m.membershipTypes.join(', ') || 'ΓÇö'}</div>                      <div class="lbl">EC Member</div><div class="val">${m.isECMember ? '<span style="color:var(--green)">Yes</span>' : 'No'}</div>                      <div class="lbl">Comms Count</div><div class="val">${m.communications || 0}</div>                    </div>                  </div>                </div>              </div>              ${m.orgRoles.length > 0 ? `              <div class="detail-section">                <h6><i class="fas fa-id-badge me-1"></i>Org Roles (${m.orgRoles.length})</h6>                ${m.orgRoles.map(r => `<span class="source-badge admin">${r.term}: ${r.role}</span>`).join(' ')}              </div>` : ''}              ${m.jagritiContributions.length > 0 ? `              <div class="detail-section">                <h6><i class="fas fa-book me-1"></i>Jagriti Contributions</h6>                ${m.jagritiContributions.map(j => `<span class="source-badge jagriti">Jagriti ${j.year}: ${j.type}</span>`).join(' ')}              </div>` : ''}              ${m.paymentRecords.length > 0 ? `              <div class="detail-section">                <h6><i class="fas fa-credit-card me-1"></i>Payment Records (${m.paymentRecords.length})</h6>                ${m.paymentRecords.map(p => `<span class="source-badge membership">${p.year}: ${p.category} $${p.amount}</span>`).join(' ')}              </div>` : ''}              <div class="detail-section">                <h6><i class="fas fa-layer-group me-1"></i>Data Sources</h6>                ${m.importSources.map(s => `<span class="source-badge ${s.includes('crm') ? 'crm' : s.includes('google') ? 'google' : s.includes('family') ? 'family' : s.includes('membership') ? 'membership' : s.includes('audit') ? 'audit' : s.includes('jagriti') ? 'jagriti' : s.includes('admin') ? 'admin' : 'other'}">${s}</span>`).join(' ')}              </div>            </div>          </td>        </tr>`).join('\n')}      </tbody>    </table>  </div></div><!-- ΓòÉΓòÉΓòÉ TAB: FAMILIES ΓòÉΓòÉΓòÉ --><div class="tab-content" id="tab-families">  <h5 style="color:var(--accent);margin-bottom:16px"><i class="fas fa-people-roof me-1"></i>${totalFamilies} Families</h5>  <input class="search-box" id="familySearch" placeholder="Search families..." oninput="filterFamilies()">  <div style="max-height:70vh;overflow-y:auto">    <table id="familyTable">      <thead><tr><th>#</th><th>Family</th><th>Type</th><th>Members</th><th>Years</th></tr></thead>      <tbody>        ${Object.entries(familyMap).sort((a,b) => b[1].length - a[1].length).map(([fid, fms], i) => {            const name = fms[0].familyDisplayName || fms.map(m => m.lastName).filter(Boolean)[0] || fid;            const allYears = [...new Set(fms.flatMap(m => m.membershipYears))].sort();            return `<tr class="family-row" data-search="${norm(name + ' ' + fid + ' ' + fms.map(m => m.displayName + ' ' + m.email).join(' '))}">              <td style="color:var(--dim)">${i+1}</td>              <td><strong>${name}</strong><br><span style="font-size:.65rem;color:var(--dim)">${fid}</span></td>              <td><span class="family-tag">${fms[0].familyType || 'ΓÇö'}</span></td>              <td>${fms.map(m => `<div style="font-size:.78rem">${m.firstName} ${m.lastName} <span style="color:var(--dim)">${m.email}</span></div>`).join('')}</td>              <td>${allYears.map(y => `<span class="badge-year">${y}</span>`).join('')}</td>            </tr>`;        }).join('\n')}      </tbody>    </table>  </div></div><!-- ΓòÉΓòÉΓòÉ TAB: DATA GAPS ΓòÉΓòÉΓòÉ --><div class="tab-content" id="tab-gaps">  <h5 style="color:var(--accent);margin-bottom:16px"><i class="fas fa-exclamation-triangle me-1"></i>Data Gaps & Issues</h5>  <div class="row g-3">    <div class="col-md-6">      <div style="background:var(--card);border:1px solid var(--line);border-radius:12px;padding:20px">        <h6 style="color:var(--yellow)"><i class="fas fa-phone-slash me-1"></i>Missing Phone (${totalMembers - withPhone})</h6>        <div style="max-height:300px;overflow-y:auto;font-size:.78rem">          ${members.filter(m => !m.phone).slice(0, 50).map(m => `<div style="padding:3px 0;border-bottom:1px solid var(--line)">${m.displayName} <span style="color:var(--dim)">(${m.email})</span></div>`).join('\n')}        </div>      </div>    </div>    <div class="col-md-6">      <div style="background:var(--card);border:1px solid var(--line);border-radius:12px;padding:20px">        <h6 style="color:var(--red)"><i class="fas fa-user-slash me-1"></i>Name Issues (${noName})</h6>        <div style="max-height:300px;overflow-y:auto;font-size:.78rem">          ${members.filter(m => !m.firstName || m.firstName === m.email).map(m => `<div style="padding:3px 0;border-bottom:1px solid var(--line)">${m.email} <span style="color:var(--dim)">ΓÇö no proper name</span></div>`).join('\n')}        </div>      </div>    </div>    <div class="col-md-6">      <div style="background:var(--card);border:1px solid var(--line);border-radius:12px;padding:20px">        <h6 style="color:var(--purple)"><i class="fas fa-unlink me-1"></i>No Family Link (${totalMembers - withFamily})</h6>        <div style="max-height:300px;overflow-y:auto;font-size:.78rem">          ${members.filter(m => !m.familyId).map(m => `<div style="padding:3px 0;border-bottom:1px solid var(--line)">${m.displayName} <span style="color:var(--dim)">(${m.email})</span></div>`).join('\n')}        </div>      </div>    </div>    <div class="col-md-6">      <div style="background:var(--card);border:1px solid var(--line);border-radius:12px;padding:20px">        <h6 style="color:var(--yellow)"><i class="fas fa-file-excel me-1"></i>Unmatched XLSX Names (${unmatchedNames.length})</h6>        <div style="max-height:300px;overflow-y:auto;font-size:.78rem">          ${unmatchedNames.map(m => `<div style="padding:3px 0;border-bottom:1px solid var(--line)">${m.name} <span style="color:var(--dim)">${m.category} ΓÇö $${m.amount}</span></div>`).join('\n')}        </div>      </div>    </div>  </div>  <div style="margin-top:16px;background:var(--card);border:1px solid var(--line);border-radius:12px;padding:20px">    <h6 style="color:var(--cyan)"><i class="fas fa-not-equal me-1"></i>Google Contacts NOT in CRM (${sources.googleContacts.filter(c => c.email && !universe.has(norm(c.email))).length})</h6>    <div style="max-height:200px;overflow-y:auto;font-size:.78rem">      ${sources.googleContacts.filter(c => c.email && ![...universe.keys()].includes(norm(c.email))).map(c => `<div style="padding:3px 0;border-bottom:1px solid var(--line)">${c.displayName} <span style="color:var(--dim)">(${c.email})</span> ${c.phone ? `≡ƒô▒${c.phone}` : ''}</div>`).join('\n') || '<span style="color:var(--green)">All Google contacts are in the CRM!</span>'}    </div>  </div></div><!-- ΓòÉΓòÉΓòÉ TAB: PLAN ΓòÉΓòÉΓòÉ --><div class="tab-content" id="tab-plan">  <h5 style="color:var(--accent);margin-bottom:16px"><i class="fas fa-clipboard-list me-1"></i>CRM Enrichment Plan</h5>  <div class="plan-step"><span class="status done">Γ£ô DONE</span><h6>1. Audit All Data Sources</h6><p>Identified 10 data sources: Live CRM API (180 members), Google Contacts (165), Family Universe XLSX (105 families, 226 individuals), Membership 2025-26 XLSX (149 payments), Family Fix Mapping (135 families), Member Audit (168), CRM Comprehensive Data (165), Admin Report (EC roles), Jagriti contributors (2022+2023), Report Family Mapping (58 families).</p></div>  <div class="plan-step"><span class="status done">Γ£ô DONE</span><h6>2. Build Unified Member Universe</h6><p>Merged all sources by email address into ${totalMembers} unique member records. Cross-referenced names, phones, family links, membership years, payment data, EC roles, and Jagriti contributions.</p></div>  <div class="plan-step"><span class="status done">Γ£ô DONE</span><h6>3. Generate Data Quality Report</h6><p>Identified ${totalMembers - withPhone} members missing phone, ${noName} with name issues, ${totalMembers - withFamily} without family links, ${unmatchedNames.length} unmatched XLSX names.</p></div>  <div class="plan-step"><span class="status ${ENRICH ? 'done' : 'pending'}">Γ¼ñ</span><h6>4. CRM Enrichment ΓÇö Push Updates</h6><p>Run with --enrich flag to push merged data (names, phones, family links) from Google Contacts and XLSX files into live CRM. ${enrichResult ? `Updated: ${enrichResult.updated}` : 'Pending'}</p></div>  <div class="plan-step"><span class="status pending">Γ¼ñ</span><h6>5. Google Drive Member Files Scan</h6><p>Use /gdrive_search API to find member lists, payment receipts, and year-specific documents on Google Drive. Cross-reference with CRM records for historical data.</p></div>  <div class="plan-step"><span class="status pending">Γ¼ñ</span><h6>6. Communication History Import</h6><p>Import email response data from communication drives into MemberCommunications collection. Link by email address.</p></div>  <div class="plan-step"><span class="status pending">Γ¼ñ</span><h6>7. Payment History Backfill</h6><p>Import historical payment data from Membership XLSX files (2022-26) into Payments collection. Link by member email/family.</p></div>  <div class="plan-step"><span class="status pending">Γ¼ñ</span><h6>8. Family Linkage Verification</h6><p>Cross-reference Family Universe v3 with existing CRM family groups. Fix orphaned members and incorrect family assignments.</p></div>  <div class="plan-step"><span class="status todo">Γùï</span><h6>9. Ongoing: New Member Onboarding</h6><p>All new members added through Membership Drive should auto-create CRM records with full profile data, family links, and payment records.</p></div>  <div class="plan-step"><span class="status todo">Γùï</span><h6>10. Ongoing: Annual XLSX Ingest</h6><p>Each year's membership XLSX should be ingested to update membership years, payment records, and maintain the member universe pool.</p></div></div><!-- ΓòÉΓòÉΓòÉ TAB: SOURCES ΓòÉΓòÉΓòÉ --><div class="tab-content" id="tab-sources">  <h5 style="color:var(--accent);margin-bottom:16px"><i class="fas fa-layer-group me-1"></i>Data Source Inventory</h5>  <div class="row g-3">    <div class="col-md-6">      <div style="background:var(--card);border:1px solid var(--line);border-radius:12px;padding:20px">        <h6 style="color:var(--blue)"><i class="fas fa-cloud me-1"></i>Live APIs</h6>        <table style="font-size:.78rem"><thead><tr><th>Endpoint</th><th>Records</th></tr></thead><tbody>          <tr><td>GET /crm_members</td><td>${sources.crmMembers.length}</td></tr>          <tr><td>GET /crm_families</td><td>${totalFamilies}</td></tr>          <tr><td>GET /crm_dashboard</td><td>180 total</td></tr>        </tbody></table>      </div>    </div>    <div class="col-md-6">      <div style="background:var(--card);border:1px solid var(--line);border-radius:12px;padding:20px">        <h6 style="color:var(--green)"><i class="fas fa-file-code me-1"></i>JSON Files</h6>        <table style="font-size:.78rem"><thead><tr><th>File</th><th>Records</th></tr></thead><tbody>          <tr><td>google_contacts.json</td><td>${sources.googleContacts.length}</td></tr>          <tr><td>family-fix-mapping.json</td><td>${sources.familyFixMapping.length} families</td></tr>          <tr><td>member-audit-all.json</td><td>${sources.memberAudit.length}</td></tr>          <tr><td>crm-comprehensive-data.json</td><td>${sources.crmComprehensive.length}</td></tr>          <tr><td>report_25-26_admin.json</td><td>${sources.adminReport ? 'loaded' : 'N/A'}</td></tr>          <tr><td>report_25-26_family_mapping.json</td><td>${sources.reportFamilyMapping.length} families</td></tr>        </tbody></table>      </div>    </div>    <div class="col-md-6">      <div style="background:var(--card);border:1px solid var(--line);border-radius:12px;padding:20px">        <h6 style="color:var(--purple)"><i class="fas fa-file-excel me-1"></i>XLSX Files</h6>        <table style="font-size:.78rem"><thead><tr><th>File</th><th>Records</th></tr></thead><tbody>          <tr><td>BANF_Family_Universe_v3.xlsx ΓåÆ Family Universe</td><td>${sources.familyUniverse.length} families</td></tr>          <tr><td>BANF_Family_Universe_v3.xlsx ΓåÆ Family Members</td><td>${sources.familyMembers.length} individuals</td></tr>          <tr><td>BANF_Family_Universe_v3.xlsx ΓåÆ Yearly</td><td>${sources.yearlyMembership.length} records</td></tr>          <tr><td>BANF_Family_Universe_v3.xlsx ΓåÆ Raw Entries</td><td>${sources.rawEntries.length} entries</td></tr>          <tr><td>BANF Membership 2025-26.xlsx</td><td>${sources.membership2526.length} members</td></tr>          <tr><td>Jagriti 2022.xlsx</td><td>${sources.jagriti2022.length} contributors</td></tr>          <tr><td>Jagriti 2023.xlsx</td><td>${sources.jagriti2023.length} contributors</td></tr>        </tbody></table>      </div>    </div>    <div class="col-md-6">      <div style="background:var(--card);border:1px solid var(--line);border-radius:12px;padding:20px">        <h6 style="color:var(--cyan)"><i class="fab fa-google-drive me-1"></i>Google Drive (Pending Scan)</h6>        <table style="font-size:.78rem"><thead><tr><th>Type</th><th>Status</th></tr></thead><tbody>          <tr><td>Member lists (annual)</td><td><span style="color:var(--yellow)">Scan needed</span></td></tr>          <tr><td>Payment screenshots/receipts</td><td><span style="color:var(--yellow)">Scan needed</span></td></tr>          <tr><td>EC meeting minutes</td><td><span style="color:var(--yellow)">Scan needed</span></td></tr>          <tr><td>Event attendance</td><td><span style="color:var(--yellow)">Scan needed</span></td></tr>        </tbody></table>        <p style="font-size:.72rem;color:var(--dim);margin-top:8px">Use /gdrive_search API to scan for member-related files</p>      </div>    </div>  </div></div></div><!-- /container --><script>function showTab(id) {  document.querySelectorAll('.tab-content').forEach(t => t.classList.remove('active'));  document.querySelectorAll('.tab-btn').forEach(b => b.classList.remove('active'));  document.getElementById('tab-' + id).classList.add('active');  event.target.closest('.tab-btn').classList.add('active');}function toggleDetail(idx) {  const row = document.getElementById('detail-' + idx);  row.style.display = row.style.display === 'none' ? '' : 'none';}function filterMembers() {  const q = document.getElementById('memberSearch').value.toLowerCase();  let count = 0;  document.querySelectorAll('.member-row').forEach(r => {    const match = !q || r.dataset.search.includes(q);    r.style.display = match ? '' : 'none';    // Also hide detail rows    const idx = r.dataset.idx;    if (!match) document.getElementById('detail-' + idx).style.display = 'none';    if (match) count++;  });  document.getElementById('memberCount').textContent = count;}function filterFamilies() {  const q = document.getElementById('familySearch').value.toLowerCase();  document.querySelectorAll('.family-row').forEach(r => {    r.style.display = !q || r.dataset.search.includes(q) ? '' : 'none';  });}</script></body></html>`;    return html;}// ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ// MAIN// ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓ